CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', parcours text NOT NULL DEFAULT 'naturalisation' CHECK (parcours IN ('naturalisation','resident','sejour')), locale text NOT NULL DEFAULT 'fr' CHECK (locale IN ('fr','zh','en','ar','es','ru')), goal_date date, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile read" ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_learning_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (new.id,coalesce(new.raw_user_meta_data->>'display_name','')); RETURN new; END $$;
CREATE TRIGGER create_learning_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_learning_profile();
CREATE TABLE public.learning_lessons (id text PRIMARY KEY, title text NOT NULL, topic text NOT NULL, position integer NOT NULL UNIQUE, body text[] NOT NULL, published boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.learning_lessons TO anon,authenticated; GRANT ALL ON public.learning_lessons TO service_role;
ALTER TABLE public.learning_lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published lessons" ON public.learning_lessons FOR SELECT TO anon,authenticated USING(published);
CREATE TABLE public.learning_questions (id text PRIMARY KEY, theme text NOT NULL, question text NOT NULL, options text[] NOT NULL, answer integer NOT NULL, explanation text NOT NULL, source text NOT NULL, position integer NOT NULL UNIQUE, published boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.learning_questions TO anon,authenticated; GRANT ALL ON public.learning_questions TO service_role;
ALTER TABLE public.learning_questions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published questions" ON public.learning_questions FOR SELECT TO anon,authenticated USING(published);
CREATE TABLE public.learning_completions (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, parcours text NOT NULL, lesson_id text NOT NULL REFERENCES public.learning_lessons(id), completed_at timestamptz NOT NULL DEFAULT now(), xp integer NOT NULL DEFAULT 40, PRIMARY KEY(user_id,parcours,lesson_id));
GRANT SELECT ON public.learning_completions TO authenticated; GRANT ALL ON public.learning_completions TO service_role;
ALTER TABLE public.learning_completions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own completions" ON public.learning_completions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.learning_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, parcours text NOT NULL, answers jsonb NOT NULL, correct integer NOT NULL, total integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.learning_attempts TO authenticated; GRANT ALL ON public.learning_attempts TO service_role;
ALTER TABLE public.learning_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own attempts" ON public.learning_attempts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.complete_learning_lesson(p_lesson text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; n integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; SELECT parcours INTO p FROM public.profiles WHERE id=auth.uid(); SELECT position INTO n FROM public.learning_lessons WHERE id=p_lesson AND published; IF n IS NULL THEN RAISE EXCEPTION 'Lesson unavailable'; END IF; IF EXISTS(SELECT 1 FROM public.learning_lessons l WHERE l.published AND l.position<n AND NOT EXISTS(SELECT 1 FROM public.learning_completions c WHERE c.user_id=auth.uid() AND c.parcours=p AND c.lesson_id=l.id)) THEN RAISE EXCEPTION 'Complete the previous lesson first'; END IF; INSERT INTO public.learning_completions(user_id,parcours,lesson_id) VALUES(auth.uid(),p,p_lesson) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.complete_learning_lesson(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.complete_learning_lesson(text) TO authenticated;
CREATE FUNCTION public.record_learning_attempt(p_answers jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; s integer; t integer; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF jsonb_typeof(p_answers)<>'array' THEN RAISE EXCEPTION 'Invalid answers'; END IF; SELECT count(*), count(*) FILTER(WHERE (p_answers->>(position-1))::integer=answer) INTO t,s FROM public.learning_questions WHERE published; IF jsonb_array_length(p_answers)<>t THEN RAISE EXCEPTION 'Invalid answer count'; END IF; SELECT parcours INTO p FROM public.profiles WHERE id=auth.uid(); INSERT INTO public.learning_attempts(user_id,parcours,answers,correct,total) VALUES(auth.uid(),p,p_answers,s,t) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.record_learning_attempt(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_learning_attempt(jsonb) TO authenticated;
