('q9','Institutions','Quelles assemblées composent le Parlement ?',ARRAY['L’Assemblée nationale et le Sénat','Le Sénat et le Conseil d’État','Les mairies et les préfectures','Le Gouvernement et les tribunaux'],0,'Le Parlement comprend l’Assemblée nationale et le Sénat.','Constitution, article 24',9,true),
('q10','Histoire et symboles','Quelles sont les couleurs du drapeau français ?',ARRAY['Bleu, blanc, rouge','Vert, blanc, rouge','Noir, rouge, jaune','Bleu, jaune, rouge'],0,'L’emblème national est le drapeau tricolore bleu, blanc, rouge.','Constitution, article 2',10,true);